import React, { useState } from 'react';
import axios from 'axios';
import * as cheerio from 'cheerio';
import './NewsScraper.css';

const NewsScraper = () => {
  const [url, setUrl] = useState('');
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('');
  const [sortBy, setSortBy] = useState('date');

  const scrapeNews = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.get(url);
      const $ = cheerio.load(response.data);
      const newsItems = [];

      // Extract news items (this is a basic example - you'll need to adjust selectors based on target website)
      $('article, .article, .news-item').each((i, element) => {
        const headline = $(element).find('h1, h2, .headline').first().text().trim();
        const author = $(element).find('.author, .byline').first().text().trim();
        const date = $(element).find('.date, .published').first().text().trim();
        const source = new URL(url).hostname;

        if (headline) {
          newsItems.push({
            headline,
            author: author || 'Unknown',
            date: date || 'No date available',
            source,
            url: $(element).find('a').first().attr('href') || url
          });
        }
      });

      setNews(newsItems);
    } catch (err) {
      setError('Error scraping the website. Please check the URL and try again.');
      console.error('Scraping error:', err);
    }
    setLoading(false);
  };

  const filteredAndSortedNews = news
    .filter(item => 
      filter === '' || 
      item.headline.toLowerCase().includes(filter.toLowerCase()) ||
      item.author.toLowerCase().includes(filter.toLowerCase())
    )
    .sort((a, b) => {
      if (sortBy === 'date') {
        return new Date(b.date) - new Date(a.date);
      }
      return a.headline.localeCompare(b.headline);
    });

  return (
    <div className="news-scraper">
      <div className="controls">
        <input
          type="text"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="Enter website URL to scrape"
          className="url-input"
        />
        <button 
          onClick={scrapeNews} 
          disabled={loading || !url}
          className="scrape-button"
        >
          {loading ? 'Scraping...' : 'Scrape News'}
        </button>
      </div>

      <div className="filters">
        <input
          type="text"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          placeholder="Filter by keyword"
          className="filter-input"
        />
        <select 
          value={sortBy} 
          onChange={(e) => setSortBy(e.target.value)}
          className="sort-select"
        >
          <option value="date">Sort by Date</option>
          <option value="title">Sort by Title</option>
        </select>
      </div>

      {error && <div className="error">{error}</div>}

      {loading && (
        <div className="loading">
          <div className="spinner"></div>
          <p>Scraping in progress...</p>
        </div>
      )}

      <div className="news-list">
        {filteredAndSortedNews.map((item, index) => (
          <div key={index} className="news-item">
            <h2>{item.headline}</h2>
            <div className="news-meta">
              <span>By: {item.author}</span>
              <span>Date: {item.date}</span>
              <span>Source: {item.source}</span>
            </div>
            <a href={item.url} target="_blank" rel="noopener noreferrer">
              Read More
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};

export default NewsScraper;
